import boto3
import os

def extract_tables_from_document(file_path: str):
    """
    Extracts tables, including cell and row structure, from a document using Amazon Textract.

    Args:
        file_path: The path to the document file (e.g., PDF, JPG, PNG).

    Returns:
        A list of tables found in the document. Each table is represented as a
        list of rows, where each row is a list of strings (cell content).
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found at {file_path}")

    # Provider-identifying signal: using the boto3 SDK for Amazon Textract.
    textract_client = boto3.client("textract")

    with open(file_path, "rb") as document_file:
        document_bytes = document_file.read()

    response = textract_client.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["TABLES"]
    )

    blocks = response.get("Blocks", [])
    block_map = {block["Id"]: block for block in blocks}

    extracted_tables = []
    table_blocks = [block for block in blocks if block.get("BlockType") == "TABLE"]

    for table_block in table_blocks:
        cell_ids = []
        if 'Relationships' in table_block:
            for relationship in table_block['Relationships']:
                if relationship.get('Type') == 'CHILD':
                    cell_ids.extend(relationship.get('Ids', []))

        rows_data = {}
        max_col_index = 0

        for cid in cell_ids:
            cell = block_map.get(cid)
            if not cell or cell.get("BlockType") != "CELL":
                continue

            row_index = cell.get("RowIndex")
            col_index = cell.get("ColumnIndex")
            if not row_index or not col_index:
                continue

            cell_text = ""
            if 'Relationships' in cell:
                for relationship in cell['Relationships']:
                    if relationship.get('Type') == 'CHILD':
                        for word_id in relationship.get('Ids', []):
                            word_block = block_map.get(word_id)
                            if word_block and word_block.get("BlockType") == "WORD":
                                cell_text += word_block.get("Text", "") + " "

            if row_index not in rows_data:
                rows_data[row_index] = {}

            rows_data[row_index][col_index] = cell_text.strip()
            max_col_index = max(max_col_index, col_index)

        if not rows_data:
            continue

        max_row_index = max(rows_data.keys())
        table_grid = [["" for _ in range(max_col_index)] for _ in range(max_row_index)]

        for r_idx, cols in rows_data.items():
            for c_idx, text in cols.items():
                table_grid[r_idx - 1][c_idx - 1] = text

        extracted_tables.append(table_grid)

    return extracted_tables
